-- Версия 1.5.0. Требует supabase/sql/site_releases.sql и site_tips.sql. Повторный запуск безопасен.
-- До выкладки сайта: supabase/sql/exam_links.sql (сайт читает столбцы away_*), затем функции tg-exam, telegram-bot, tg-app.
select public.add_site_release('1.5.0','Билеты классу: кто ушёл со страницы и экран для проектора',
  jsonb_build_array(
    jsonb_build_object('kind','new','scope','site','min_rank',1,'text','Билеты классу: в таблице запуска сразу видно, кто из учеников ушёл со страницы билета (свернул Telegram, открыл другое окно или приложение) — столбец «Уходил» и всплывающее предупреждение; эти данные есть и в Excel.'),
    jsonb_build_object('kind','new','scope','site','min_rank',1,'text','Билеты классу: кнопка «На экран» открывает страницу для проектора — QR-код и список вошедших, отсчёт, крупный таймер и имена тех, кто ушёл со страницы билета.'),
    jsonb_build_object('kind','improved','scope','app','min_rank',1,'text','Бланк ответов «Химия / физика» на 12 заданий теперь печатается по пять на листе: между бланками больше места, и при разрезе угловые метки не срезаются; уже напечатанные бланки проверяются как раньше.'),
    jsonb_build_object('kind','improved','scope','bot','min_rank',1,'text','Ученику, который открыл билет по ссылке и не привязан к сайту, бот больше не показывает кнопку «Конструктор» внизу чата.')
  ),
  '2026-11-24 18:30:00+05');

select public.add_site_tip('1.5.0',
  'В «Билетах классу» таблица запуска показывает, кто ушёл со страницы билета во время сессии: смотрите столбец «Уходил». Ученик тоже видит, что вы об этом знаете.',
  'nav-exams', 'exams', 1::smallint, '2026-11-24 18:30:00+05');
select public.add_site_tip('1.5.0',
  'Запуск в «Билетах классу» можно вывести на проектор: откройте запуск и нажмите «На экран». Класс увидит QR-код, таймер и тех, кто ушёл со страницы билета.',
  'nav-exams', 'exams', 1::smallint, '2026-11-24 18:30:00+05');
